<?php $plural=$domain==='career'?'careers':'bursaries';?><h1><?=e($application['application_reference'])?></h1><p class="lead"><?=e($application['title'])?> · <?=e(str_replace('_',' ',$application['status']))?></p><?php if($domain==='career'):?><h2 class="h5">Cover letter</h2><p><?=nl2br(e($application['cover_letter']))?></p><h2 class="h5">Experience</h2><p><?=nl2br(e($application['experience_summary']))?></p><?php else:?><p><strong>Institution:</strong> <?=e($application['institution'])?></p><p><strong>Programme:</strong> <?=e($application['qualification'])?></p><p><strong>Study level:</strong> <?=e($application['study_level'])?></p><p><?=nl2br(e($application['motivation']))?></p><?php endif;?><?php if($application['decision_reason']):?><div class="alert alert-info"><?=e($application['decision_reason'])?></div><?php endif;?><h2 class="h5">Timeline</h2><ul><?php foreach($events as $event):?><li><?=e($event['created_at'].' — '.str_replace('_',' ',$event['new_status']))?><?php if($event['note']):?>: <?=e($event['note'])?><?php endif;?></li><?php endforeach;?></ul><?php if($staff):?><form method="post" class="card card-body" action="<?=e(url('/admin/'.$plural.'/applications/'.$application['application_reference'].'/status/under_review'))?>"><?=csrf_field()?><label>Applicant-visible decision reason</label><textarea name="decision_reason" class="form-control"></textarea><label class="mt-2">Private reviewer note</label><textarea name="private_reviewer_note" class="form-control"></textarea><div class="d-flex flex-wrap gap-2 mt-3"><?php $actions=$domain==='career'?['under_review','shortlisted','unsuccessful','hired']:['under_review','shortlisted','approved','unsuccessful'];foreach($actions as $action):?><button class="btn btn-outline-primary" formaction="<?=e(url('/admin/'.$plural.'/applications/'.$application['application_reference'].'/status/'.$action))?>"><?=e(ucwords(str_replace('_',' ',$action)))?></button><?php endforeach;?></div></form><?php elseif(in_array($application['status'],['submitted','under_review','shortlisted'],true)):?><form method="post" action="<?=e(url('/'.$plural.'/applications/'.$application['application_reference'].'/withdraw'))?>"><?=csrf_field()?><button class="btn btn-outline-danger">Withdraw application</button></form><?php endif;?>
